mkdir -p /tmp/svcs; cat > /tmp/svcs/track.js <<'EOF'
// usage: node track.js video r g b tol  -> per frame: t minx maxx miny maxy count
const {spawn}=require('child_process');
const [video,r,g,b,tol]=process.argv.slice(2).map((x,i)=>i?+x:x);
const W=640,H=360,FS=W*H*3;
const p=spawn('ffmpeg',['-loglevel','error','-i',video,'-f','rawvideo','-pix_fmt','rgb24','-']);
let buf=Buffer.alloc(0),f=0,out=[];
p.stdout.on('data',d=>{buf=Buffer.concat([buf,d]);while(buf.length>=FS){const fr=buf.subarray(0,FS);buf=buf.subarray(FS);
let mnx=1e9,mxx=-1,mny=1e9,mxy=-1,c=0;
for(let y=0;y<H;y++)for(let x=0;x<W;x++){const i=(y*W+x)*3;if(Math.abs(fr[i]-r)<=tol&&Math.abs(fr[i+1]-g)<=tol&&Math.abs(fr[i+2]-b)<=tol){c++;if(x<mnx)mnx=x;if(x>mxx)mxx=x;if(y<mny)mny=y;if(y>mxy)mxy=y;}}
out.push([(f/25).toFixed(2),mnx,mxx,mny,mxy,c].join(' '));f++;}});
p.on('close',()=>console.log(out.join('\n')));
EOF
cd "<home>/svc-bench-runs/claude-20261024T1347"; node /tmp/svcs/track.js jump-count.mp4 210 48 48 40 > /tmp/svc/jump.txt; awk '{print $5}' /tmp/svc/jump.txt | sort -n | uniq -c

